      { key: "well3", name: "A pump", note: "its pump card says the well is running dry", reads: "Pump cards and run times in: one well is pumping off. Check its setting." },
      { key: "comp", name: "Compressor", note: "the same alarm every night this week", reads: "Alarms and trends in: one alarm keeps coming back at night. The manual page is with it." },
      { key: "platB", name: "Platform B", note: "hours lost that its daily report does not explain", reads: "Daily reports from both platforms in: B lost hours that A did not, and its report does not say why." },
    ],
  } = $props();
</script>

